def analyze_B4(controller, references, b2_run, device, labels, run_id):
 import sys,json,time,math,collections
 from pathlib import Path
 sys.path.insert(0,'results/T-048/scripts')
 from chay import OUT,read,dump,sha
 from kiem import read_run,mechanism_case,doi_chieu_khoa
 from cham import WORLDS
 folder=OUT/'runs'/run_id;folder.mkdir();start=time.monotonic();deadline=start+10800
 (folder/'command.json').write_text(dump(dict(controller=controller,references=references,B2=b2_run,no_method_calls=True,analysis_source=ANALYSIS_SOURCE,labels_held_separately=True))+'\n',encoding='utf-8')
 while not (OUT/'runs'/controller/'kiem.json').exists() or not (OUT/'runs'/b2_run/'kiem.json').exists():
  if time.monotonic()>deadline:raise TimeoutError('B4 tới trần chờ nguồn')
  time.sleep(10)
 assert read(OUT/'runs'/controller/'kiem.json')['success']
 b2=read(OUT/'runs'/b2_run/'kiem.json');assert b2['closed'] and not b2['exceptions']
 allocation=read(OUT/'ma-tran.json')['allocation'];refs={};hashes={}
 for name in [*references,controller]:
  for child in read(OUT/'runs'/name/'kiem.json')['finished']:
   cmd,meta,pairs=read_run(OUT/'runs'/child);hashes[child]=meta
   if name in references:
    for job in cmd['plan']['jobs']:
     if allocation[job['opaque_id']]==device:refs[(job['opaque_id'],job['window'])]=child
 command=read(folder/'command.json');command.update(phase1=hashes,B2_sha256=sha(OUT/'runs'/b2_run/'kiem.json'),labels_sha256=__import__('hashlib').sha256(dump(labels).encode()).hexdigest());(folder/'command.json').write_text(dump(command)+'\n',encoding='utf-8')
 totals=collections.Counter()
 with (folder/'ban-ghi.jsonl').open('x',encoding='utf-8') as output,(folder/'trung-gian.jsonl').open('x',encoding='utf-8') as context_out,(folder/'progress.jsonl').open('x',encoding='utf-8') as progress:
  for child in read(OUT/'runs'/controller/'kiem.json')['finished']:
   cmd,meta,pairs=read_run(OUT/'runs'/child);job=cmd['plan']['jobs'][0]
   if job['window']!='that':continue
   oid=job['opaque_id'];refchild=refs[(oid,'that')];_,_,rpairs=read_run(OUT/'runs'/refchild);r0,d0=next(rpairs());batch={r['config_id']:(r,d) for r,d in pairs()};batch[r0['config_id']]=(r0,d0)
   # Root is joined here, after every native/intermediate hash was checked.
   root=labels[oid]['root']
   for base,eid in (('R0','R0-E4-S1-e0.05-a0.01'),('E1+E2','E1+E2-E4-S1')):
    er,ed=batch[eid];zr,zd=batch[base+'-z-S1'];z0r,z0d=batch[base+'-z-S0'];mechanism=mechanism_case(er,ed,zr,zd,z0r,z0d,root)
    assert 'OPEN' not in mechanism
    result=dict(opaque_id=oid,dataset=job['dataset'],cell=labels[oid]['o'],base=base,source_child=child,reference_child=refchild,root=root,mechanism=mechanism)
    output.write(dump(result)+'\n');output.flush()
    context={}
    for i,w in enumerate(WORLDS):
     rank=ed['trace']['xep'][i];zrank=zd['trace']['xep'][i];pv=ed['trace']['phan_vi'];channels=[k for k in rank['kenh'] if k['F_raw'] and k['hop_le'] and k['trang_thai']=='OK'];intrinsic=[k for k in channels if rank['F_I'].get(k['ma'])==1]
     context[w]=dict(root_ranked=root in rank['ket_qua']['tang'],root_tier=rank['ket_qua']['tang'].get(root),PV_flagged=sum(k['don_vi'] in pv for k in intrinsic),count_flagged=sum(k['don_vi'] not in pv for k in intrinsic),PV_rA1=sum(pv[k['don_vi']]['oracle'][k['huong']]['r_A_one'] for k in intrinsic if k['don_vi'] in pv),PV_e1=sum(pv[k['don_vi']]['oracle'][k['huong']]['e_one'] for k in intrinsic if k['don_vi'] in pv),root_E4=doi_chieu_khoa(rank,root,ed['trace']['don_vi_the_gioi'][i]['m']),root_z=doi_chieu_khoa(zrank,root,zd['trace']['don_vi_the_gioi'][i]['m']))
    context_out.write(dump(dict(opaque_id=oid,base=base,worlds=context))+'\n');context_out.flush();totals.update(cases=1,worlds=3,flips=sum(len(v['flips']) for v in mechanism['worlds'].values()))
   progress.write(dump(dict(child=child,cases=totals['cases'],elapsed=time.monotonic()-start))+'\n');progress.flush()
 (folder/'kiem.json').write_text(dump(dict(closed=True,totals=totals,phase1=hashes,phase2_sha256=sha(folder/'ban-ghi.jsonl'),context_sha256=sha(folder/'trung-gian.jsonl'),wall_seconds_including_wait=time.monotonic()-start))+'\n',encoding='utf-8')
 return dict(totals)
